const p = $input.first().json || {};
const errors = [];

const rawMode = p.confirm_action || p.sub_action || p.mode || 'create';
const mode = String(rawMode).toLowerCase().trim();
if (!['create', 'replace_conflict'].includes(mode)) {
  errors.push('confirm_action phai la create hoac replace_conflict');
}

const userId = String(p.user_id || p.user_email || '').trim();
if (!userId) errors.push('thieu user_id');

const isBatchEvents = Array.isArray(p.events) && p.events.length > 0;

if (isBatchEvents) {
  const reDate = /^\d{4}-\d{2}-\d{2}$/;
  const reTime = /^\d{1,2}:\d{2}/;
  p.events.forEach((ev, idx) => {
    const n = idx + 1;
    if (!ev || !ev.title) errors.push(`Su kien [${n}]: Thieu title`);
    if (!ev || !reDate.test(String(ev.date_range_start || ''))) errors.push(`Su kien [${n}]: date_range_start phai dang YYYY-MM-DD`);
    if (!ev || !reTime.test(String(ev.specific_start_time || ''))) errors.push(`Su kien [${n}]: specific_start_time phai dang HH:mm`);
    const hasEnd = ev && reTime.test(String(ev.specific_end_time || ''));
    const hasDur = ev && Number(ev.duration_minutes) > 0;
    if (!hasEnd && !hasDur) errors.push(`Su kien [${n}]: Thieu specific_end_time hoac duration_minutes`);
  });
} else {
  const rid = Number.parseInt(p.request_id, 10);
  if (!Number.isInteger(rid) || rid <= 0) errors.push('request_id phai la so nguyen duong');
  const code = String(p.selected_slot_code || '').toUpperCase().trim();
  if (!/^S[1-9]$/.test(code)) errors.push('selected_slot_code khong hop le (S1, S2, S3)');
}

if (mode === 'replace_conflict' && !p.delete_event_id) errors.push('thieu delete_event_id');

if (errors.length > 0) {
  return [{ json: { valid: false, response: { status: 'error', error_code: 'INVALID_INPUT', message: errors.join('; ') } } }];
}

const reqId = isBatchEvents ? null : Number.parseInt(p.request_id, 10);
const slotCode = isBatchEvents ? null : String(p.selected_slot_code).toUpperCase().trim();

return [{
  json: {
    valid: true,
    operation: 'get_request',
    data: { request_id: reqId },
    creation_type: isBatchEvents ? 'batch_events' : 'single_slot',
    user_id: userId,
    mode: mode,
    request_id: reqId,
    selected_slot_code: slotCode,
    slot_code: slotCode,                         // <-- cac node phia sau doc ctx.slot_code
    delete_event_id: p.delete_event_id || null,  // <-- Evaluate Conflicts / Prep Delete Old doc ctx.delete_event_id
    events: isBatchEvents ? p.events : null,
    selected_slots: p.selected_slots || null
  }
}];

const ctx = $('Validate Input').first().json;
const r = $input.first().json;
const err = (c, m) => [{ json: { ok: false, response: { status: 'error', error_code: c, request_id: ctx.request_id, slot_code: ctx.slot_code, message: m } } }];
if (!r.success) return err('DB_ERROR', 'Khong doc duoc yeu cau: ' + (r.error || ''));
const req = r.rows[0];
if (!req) return err('REQUEST_NOT_FOUND', 'Khong tim thay request_id ' + ctx.request_id);
if (req.external_user_id !== ctx.user_id) return err('FORBIDDEN', 'request_id khong thuoc ve user nay');
if (req.intent !== 'create_event') return err('INVALID_REQUEST_INTENT', 'Yeu cau nay khong phai la tao lich moi.');
return [{ json: { ok: true, operation: 'lock_slot', data: { request_id: ctx.request_id, slot_code: ctx.slot_code, allow_retry: true } } }];

const ctx = $('Validate Input').first().json;
const r = $input.first().json;
const s = r.success ? r.rows[0] : null;
let code, message;
if (!r.success) { code = 'DB_ERROR'; message = 'Khong khoa duoc phuong an: ' + (r.error || ''); }
else if (!s) { code = 'SLOT_NOT_FOUND'; message = 'Khong tim thay phuong an ' + ctx.slot_code + ' cua request ' + ctx.request_id + '.'; }
else if (s.status === 'created' || s.status === 'confirming') { code = 'ALREADY_PROCESSED'; message = 'Phuong an nay da/dang duoc xu ly (trang thai: ' + s.status + ').'; }
else if (s.status === 'expired' || Number(s.is_expired) === 1) { code = 'PROPOSAL_EXPIRED'; message = 'Phuong an da het han; vui long tao yeu cau moi.'; }
else { code = 'SLOT_NOT_AVAILABLE'; message = 'Phuong an khong o trang thai co the xac nhan (' + s.status + ').'; }
return [{ json: { response: { status: 'error', error_code: code, request_id: ctx.request_id, slot_code: ctx.slot_code, slot_status: s ? s.status : null, message } } }];

const lock = $input.first().json.rows[0];
const toIso = (s) => String(s).replace(' ', 'T') + '+07:00';
return [{ json: { time_min: toIso(lock.start_time), time_max: toIso(lock.end_time) } }];

const ctx = $('Validate Input').first().json;
const res = $input.first().json;
const myId = 'aisec' + ctx.request_id + ctx.slot_code.toLowerCase();
const base = { request_id: ctx.request_id, slot_code: ctx.slot_code };
if (res.error || !Array.isArray(res.items)) {
  return [{ json: { blocked: true, slot_status: 'failed', response: { status: 'error', error_code: 'GCAL_CHECK_FAILED', ...base, message: 'Khong kiem tra duoc xung dot tren Google Calendar; vui long thu lai.' } } }];
}
const conflicts = res.items
  .filter((ev) => ev.status !== 'cancelled' && ev.transparency !== 'transparent' && ev.id !== myId && ev.id !== ctx.delete_event_id)
  .map((ev) => ({ event_id: ev.id, title: ev.summary || '(khong tieu de)', start_time: (ev.start && (ev.start.dateTime || ev.start.date)) || null, end_time: (ev.end && (ev.end.dateTime || ev.end.date)) || null }));
if (conflicts.length > 0) {
  return [{ json: { blocked: true, slot_status: 'slot_taken', response: { status: 'slot_taken', ...base, conflicts, message: 'Khung gio nay da co lich khac. Gui confirm_action=replace_conflict kem delete_event_id de thay the, hoac chon phuong an khac.' } } }];
}
return [{ json: { blocked: false } }];

const ctx = $('Validate Input').first().json;
const r = ($input.first().json.response) || {};
return [{ json: { slot_status: 'failed', response: { status: 'error', error_code: 'DELETE_CONFLICT_FAILED', request_id: ctx.request_id, slot_code: ctx.slot_code, message: 'Khong xoa duoc lich cu: ' + (r.message || r.error_code || r.status || 'khong ro') } } }];

const ctx = $('Validate Input').first().json;
const lock = $('Call 09 - Lock Slot').first().json.rows[0];
const req = $('Call 09 - Get Request').first().json.rows[0];
let parsed = {};
try { parsed = JSON.parse(req.parsed_json || '{}'); } catch (e) { parsed = {}; }
const toIso = (s) => String(s).replace(' ', 'T') + '+07:00';
const title = parsed.title || String(req.user_command || 'Su kien moi').slice(0, 100);
const eventId = 'aisec' + ctx.request_id + ctx.slot_code.toLowerCase(); // id co dinh => chong tao trung (409)
const body = {
  id: eventId,
  summary: title,
  location: parsed.location || undefined,
  description: 'Tạo bởi AI Secretary (request #' + ctx.request_id + ', phương án ' + ctx.slot_code + ')',
  start: { dateTime: toIso(lock.start_time), timeZone: 'Asia/Ho_Chi_Minh' },
  end: { dateTime: toIso(lock.end_time), timeZone: 'Asia/Ho_Chi_Minh' },
  reminders: { useDefault: false, overrides: [{ method: 'popup', minutes: 30 }] } // Google Calendar native reminder
};
return [{ json: { gcal_body: body, event_id: eventId, title, location: parsed.location || null } }];

const ctx = $('Validate Input').first().json;
const prep = $('Prep GCal Create').first().json;
const res = $input.first().json;
const code = res.statusCode;
if (code === 200 || code === 201) {
  const b = res.body || {};
  return [{ json: { gcal_ok: true, google_event_id: b.id || prep.event_id, html_link: b.htmlLink || null, already_existed: false } }];
}
if (code === 409) { // id da ton tai: lan truoc da tao xong => dung lai, khong tao trung
  return [{ json: { gcal_ok: true, google_event_id: prep.event_id, html_link: null, already_existed: true } }];
}
const detail = code ? 'HTTP ' + code : (typeof res.error === 'string' ? res.error : (res.error && res.error.message) || 'khong ro');
return [{ json: { gcal_ok: false, slot_status: 'failed', response: { status: 'error', error_code: 'GCAL_CREATE_FAILED', request_id: ctx.request_id, slot_code: ctx.slot_code, message: 'Google Calendar tu choi tao lich (' + detail + '). Ban co the bam thu lai.' } } }];

const ctx = $('Validate Input').first().json;
const lock = $('Call 09 - Lock Slot').first().json.rows[0];
const req = $('Call 09 - Get Request').first().json.rows[0];
const prep = $('Prep GCal Create').first().json;
const g = $input.first().json;
return [{ json: { operation: 'insert_event', data: {
  request_id: ctx.request_id, user_id: req.user_id, title: prep.title, location: prep.location,
  start_time: lock.start_time, end_time: lock.end_time, google_event_id: g.google_event_id
} } }];

const ctx = $('Validate Input').first().json;
const g = $('Interpret GCal Result').first().json;
return [{ json: { slot_status: 'failed', response: { status: 'error', error_code: 'SQL_SAVE_FAILED', request_id: ctx.request_id, slot_code: ctx.slot_code, google_event_id: g.google_event_id, message: 'Da tao lich tren Google Calendar nhung chua luu duoc vao CSDL. Bam thu lai de dong bo (he thong se khong tao trung lich).' } } }];

const ev = $input.first().json.rows[0];
const start = new Date(ev.start_time.replace(' ', 'T') + '+07:00').getTime();
const rem = new Date(start - 30 * 60000 + 7 * 3600000).toISOString().slice(0, 19).replace('T', ' ');
return [{ json: { operation: 'insert_reminder', event: ev, data: { event_id: ev.event_id, thoi_gian_nhac: rem, noi_dung_nhac: 'Sap dien ra: ' + ev.title + ' luc ' + ev.start_time.slice(11, 16) } } }];

const ctx = $('Validate Input').first().json;
const req = $('Call 09 - Get Request').first().json.rows[0];
const g = $('Interpret GCal Result').first().json;
return [{ json: { operation: 'finalize_create', data: { request_id: ctx.request_id, slot_code: ctx.slot_code, google_event_id: g.google_event_id, user_command: req.user_command, ai_analysis_json: req.parsed_json } } }];

const ctx = $('Validate Input').first().json;
const pr = $('Prep Reminder').first().json;
const g = $('Interpret GCal Result').first().json;
const rem = $('Call 09 - Insert Reminder').first().json;
const fin = $input.first().json;
const warnings = [];
if (!rem || rem.success === false) warnings.push({ code: 'REMINDER_NOT_SAVED', message: 'Chua luu duoc nhac nho noi bo.' });
if (!fin || fin.success === false) warnings.push({ code: 'FINALIZE_FAILED', message: 'Lich da tao nhung chua cap nhat trang thai phuong an/yeu cau.' });
return [{ json: { response: {
  status: 'created',
  request_id: ctx.request_id,
  slot_code: ctx.slot_code,
  already_existed: g.already_existed,
  replaced_event_id: ctx.delete_event_id,
  event: {
    event_id: pr.event.event_id, google_event_id: g.google_event_id, title: pr.event.title, location: pr.event.location,
    start_time: pr.event.start_time, end_time: pr.event.end_time, html_link: g.html_link
  },
  warnings
} } }];

const ctx = $('Validate Input').first().json;
const f = $input.first().json;
return [{ json: { operation: 'update_slot_status', data: { request_id: ctx.request_id, slot_code: ctx.slot_code, status: f.slot_status }, response: f.response } }];

const r = $input.first().json;
const ctx = $('Validate Input').first().json;
const notFound = r.success && !(r.rows && r.rows.length);
return [{ json: { response: {
  status: 'error',
  error_code: notFound ? 'USER_NOT_FOUND' : 'DB_ERROR',
  message: notFound ? ('Khong tim thay nguoi dung ' + ctx.user_id) : ('Khong doc duoc nguoi dung: ' + (r.error || ''))
} } }];

const ctx = $('Validate Input').first().json;
const u = $input.first().json;
const dbUserId = u.rows[0].user_id;

const pad = (n) => String(n).padStart(2, '0');
const parseHM = (s) => { const m = String(s || '').match(/^(\d{1,2}):(\d{2})/); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
const fmt = (ms) => { const t = new Date(ms); return `${t.getUTCFullYear()}-${pad(t.getUTCMonth() + 1)}-${pad(t.getUTCDate())} ${pad(t.getUTCHours())}:${pad(t.getUTCMinutes())}:00`; };
const hash = (s, seed) => { let h = seed; for (const ch of s) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(16).padStart(8, '0'); };
const toIso = (s) => s.replace(' ', 'T') + '+07:00';

return ctx.events.map((ev, idx) => {
  const [y, m, d] = ev.date_range_start.split('-').map(Number);
  const startMin = parseHM(ev.specific_start_time);
  let endMin = parseHM(ev.specific_end_time);
  if (endMin === null || endMin <= startMin) endMin = startMin + (Number(ev.duration_minutes) > 0 ? Number(ev.duration_minutes) : 60);
  const base = Date.UTC(y, m - 1, d, 0, 0, 0);
  const start_time = fmt(base + startMin * 60000);
  const end_time = fmt(base + endMin * 60000);
  const key = [ctx.user_id, ev.title, start_time].join('|');
  // Google event id: chi gom 0-9 a-v => co dinh theo (user, title, gio bat dau) => chong tao trung (409)
  const event_id = 'aisecb' + start_time.replace(/\D/g, '').slice(0, 12) + hash(key, 5381) + hash(key, 52711);
  const title = String(ev.title).slice(0, 200);
  return { json: {
    idx, event_id, title, start_time, end_time, db_user_id: dbUserId,
    gcal_body: {
      id: event_id,
      summary: title,
      description: 'Tạo bởi AI Secretary',
      start: { dateTime: toIso(start_time), timeZone: 'Asia/Ho_Chi_Minh' },
      end: { dateTime: toIso(end_time), timeZone: 'Asia/Ho_Chi_Minh' },
      reminders: { useDefault: false, overrides: [{ method: 'popup', minutes: 30 }] }
    }
  } };
});

const built = $('Batch Build Events').all();
return $input.all().map((it, i) => {
  const b = built[i].json;
  const res = it.json || {};
  const out = { idx: b.idx, event_id: b.event_id, title: b.title, start_time: b.start_time, end_time: b.end_time, db_user_id: b.db_user_id };
  if (res.id && !res.error) {
    return { json: { ...out, gcal_ok: true, google_event_id: res.id, html_link: res.htmlLink || null, already_existed: false } };
  }
  const e = res.error;
  const detail = typeof e === 'string' ? e : ((e && (e.message || e.description)) || 'khong ro');
  return { json: { ...out, gcal_ok: false, google_event_id: null, html_link: null, already_existed: false, gcal_error: detail } };
});

// Moi item phai co 1 operation hop le de WF09 khong sinh sql = null.
// Su kien tao Google that bai -> thao tac doc nhe (get_user), khong ghi DB.
const ctx = $('Validate Input').first().json;
return $input.all().map((it) => {
  const b = it.json;
  if (b.gcal_ok) {
    return { json: { operation: 'insert_event', data: {
      request_id: null, user_id: b.db_user_id, title: b.title, location: null,
      start_time: b.start_time, end_time: b.end_time, google_event_id: b.google_event_id
    } } };
  }
  return { json: { operation: 'get_user', data: { external_user_id: ctx.user_id } } };
});

const ctx = $('Validate Input').first().json;
const interp = $('Batch Interpret').all();
return $input.all().map((it, i) => {
  const b = interp[i].json;
  const r = it.json || {};
  const ev = r.success && r.rows && r.rows[0];
  // chi nhac cho su kien MOI tao (da ton tai tren Google => bo qua de khong nhac trung)
  if (b.gcal_ok && !b.already_existed && ev && ev.event_id) {
    const start = new Date(ev.start_time.replace(' ', 'T') + '+07:00').getTime();
    const rem = new Date(start - 30 * 60000 + 7 * 3600000).toISOString().slice(0, 19).replace('T', ' ');
    return { json: { operation: 'insert_reminder', data: { event_id: ev.event_id, thoi_gian_nhac: rem, noi_dung_nhac: 'Sap dien ra: ' + ev.title + ' luc ' + ev.start_time.slice(11, 16) } } };
  }
  return { json: { operation: 'get_user', data: { external_user_id: ctx.user_id } } };
});

const interp = $('Batch Interpret').all();
const ins = $('Call 09 - Batch Insert Event').all();
const rem = $input.all();
const results = [];
const warnings = [];
interp.forEach((it, i) => {
  const b = it.json;
  const r = (ins[i] && ins[i].json) || {};
  const saved = !!(b.gcal_ok && r.success && r.rows && r.rows.length);
  if (b.gcal_ok && !saved) warnings.push({ code: 'SQL_SAVE_FAILED', title: b.title, message: 'Da tao tren Google Calendar nhung chua luu duoc vao CSDL.' });
  const rm = (rem[i] && rem[i].json) || {};
  if (b.gcal_ok && !b.already_existed && saved && rm.success === false) warnings.push({ code: 'REMINDER_NOT_SAVED', title: b.title, message: 'Chua luu duoc nhac nho noi bo.' });
  results.push({
    index: b.idx,
    title: b.title,
    start_time: b.start_time,
    end_time: b.end_time,
    status: b.gcal_ok ? 'created' : 'error',
    already_existed: b.already_existed,
    google_event_id: b.google_event_id,
    html_link: b.html_link,
    saved_to_db: saved,
    error_code: b.gcal_ok ? undefined : 'GCAL_CREATE_FAILED',
    message: b.gcal_ok ? undefined : 'Google Calendar tu choi tao lich (' + b.gcal_error + ').'
  });
});
const created = results.filter((x) => x.status === 'created').length;
const failed = results.length - created;
return [{ json: { response: {
  status: failed === 0 ? 'created' : (created === 0 ? 'error' : 'partial'),
  error_code: created === 0 ? 'GCAL_CREATE_FAILED' : undefined,
  message: failed === 0 ? ('Da tao ' + created + ' su kien tren Google Calendar.') : ('Da tao ' + created + ', loi ' + failed + '. ' + (results.find((x) => x.status === 'error') || {}).message),
  creation_type: 'batch_events',
  created_count: created,
  failed_count: failed,
  total: results.length,
  results,
  warnings
} } }];
